import hashlib,json
from pathlib import Path
root=Path('docs/evidence/runs'); data={}; walls={}; ids={key:set() for key in ('attempt_id','artifact_id','observation_id')}
for epoch in ('target','full'):
 rows=[]; walls[epoch]=[]
 for domain in ('sorting','compression'):
  for variant in ('default','counterfactual'):
   name=domain+'_'+variant
   path=root/('v1-07a-'+epoch+'-'+name+'.json'); raw=path.read_bytes(); value=json.loads(raw)
   data[epoch,name]=value; walls[epoch].append(value['wall_seconds'])
   rows.append({'name':name,'sha256':hashlib.sha256(raw).hexdigest(),'cli_wall_seconds':value['wall_seconds']})
   for key, records in [('attempt_id',value['database']['execution_attempts']),('artifact_id',value['artifacts']),('observation_id',value['observations'])]:
    for item in records:
     assert item[key] not in ids[key]
     ids[key].add(item[key])
 print(json.dumps({'epoch':epoch,'reports':rows},sort_keys=True))
for name in ('sorting_default','sorting_counterfactual','compression_default','compression_counterfactual'):
 def facts(value):
  return sorted((o['values']['candidate'],o['values']['operation'],o['values']['cost'],o['validation']['status'],o['values']['dataset_sha256'],o['protocol_fingerprint'],o['comparison_scope']) for o in value['observations'])
 assert facts(data['target',name])==facts(data['full',name])
assert all(len(value)==32 for value in ids.values())
print(json.dumps({'cross_epoch_independent_ids':{k:len(v) for k,v in ids.items()},'same_domain_measurement_facts':True,'cli_wall_range_seconds':{k:[min(v),max(v)] for k,v in walls.items()},'interpretation':'Two separately accounted epochs, not efficiency control arms; no best-case selection or speedup claim.'},sort_keys=True))
